function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(msg){const el=document.getElementById("toast");el.textContent=msg;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2400)}
function go(page){currentPage=page;document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.id==="page-"+page));document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===page));document.getElementById("pageCrumb").textContent=({dashboard:"Overview",companies:"Companies",interviews:"Interview experiences",resources:"Preparation resources",guidance:"Senior guidance",placements:"LPU placements",roadmap:"My roadmap",profile:"My profile",contribute:"Contribute information",admin:"Moderation"})[page]||page;document.getElementById("sidebar").classList.remove("open");if(page==="admin"){toast("Moderation tools are not enabled for student accounts.");go("dashboard");return}if(page==="roadmap")renderRoadmap();if(page==="profile")renderProfilePage();window.scrollTo({top:0,behavior:"smooth"})}
function renderDashboard(){const top=["Microsoft","Google","Amazon","Accenture","Capgemini","Cognizant","Bosch","JPMorgan Chase","BNY Mellon","Palo Alto Networks","Samsung","Cipla","TCS (Tata Consultancy Services)","Infosys"];document.getElementById("topRecruiters").innerHTML=top.map(n=>`<button class="recruiter-chip" data-recruiter="${esc(n)}">${esc(n)}</button>`).join("");document.getElementById("recruiterOfferStats").innerHTML=[["Accenture","805 offers"],["Capgemini","578 offers"],["Cognizant","263 offers"]].map(x=>`<div class="offer-stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join("");document.getElementById("statCompanies").textContent=state.companies.length;document.getElementById("statInterviews").textContent=state.interviews.length;document.getElementById("statResources").textContent=state.resources.length;document.getElementById("statPending").textContent=state.submissions.filter(s=>s.status==="Pending").length;document.getElementById("recentInterviews").innerHTML=state.interviews.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(i=>`<div class="compact-item"><div><b>${esc(i.title)}</b><small>${esc(i.company)} · ${esc(i.year)}</small></div><span class="tag">${esc(i.difficulty)}</span></div>`).join("")||'<div class="empty-state">No experiences yet.</div>';document.getElementById("focusResources").innerHTML=state.resources.slice(0,4).map(r=>`<div class="focus-row"><span class="focus-dot"></span><div><b>${esc(r.title)}</b><small>${esc(r.category)} · ${esc(r.level)}</small></div></div>`).join("");const marquee=[...new Set(state.companies.map(c=>c.name))].slice(0,70);document.getElementById("companyMarquee").innerHTML=[...marquee,...marquee].map(n=>`<span class="marquee-company">${esc(n)}</span>`).join("");const feed=state.publicPosts.slice(0,5);document.getElementById("recentCommunity").innerHTML=feed.map(x=>`<article class="community-post"><div><b>${esc(x.title)}</b><small>${esc(x.type)} · ${esc(x.company||x.role||"Student contribution")}</small></div><div class="community-author">${esc(x.authorName||"Student contributor")}<small>${esc(x.authorCourse||"LPU student")}</small></div><span class="community-unverified">Community · unverified</span></article>`).join("")||`<div class="empty-state">No student contributions yet. Be the first to share an experience, company update or preparation tip.</div>`}
function renderCompanies(){const q=(document.getElementById("companySearch").value||"").toLowerCase(),cat=document.getElementById("companyType").value,status=document.getElementById("companyStatus").value,stream=document.getElementById("companyStream")?.value||"all";const items=state.companies.filter(c=>(cat==="all"||c.category===cat)&&(status==="all"||c.status===status)&&(stream==="all"||c.stream===stream||c.stream==="Multi-stream")&&[c.name,c.roles,c.skills,c.summary,c.stream].join(" ").toLowerCase().includes(q));document.getElementById("companyCount").textContent=`Showing ${items.length} companies · ${state.companies.length} in directory`;document.getElementById("companyGrid").innerHTML=items.map(c=>`<article class="company-card"><div class="company-head"><div class="company-logo">${esc(c.name.split(/\s+/).map(x=>x[0]).slice(0,2).join("").toUpperCase())}</div><div><b>${esc(c.name)}</b><small>${esc(c.category)}</small></div></div><span class="stream-tag">${esc(c.stream||"Multi-stream")}</span><p>${esc(c.summary)}</p><div class="company-meta"><span class="status ${c.status==="Past drive"?"past":c.status==="Research"?"research":""}">${esc(c.status)}</span><button class="small-action" data-detail-company="${c.id}">View profile →</button></div></article>`).join("")||'<div class="empty-state">No matching companies. Try another stream or search.</div>'}
function renderInterviews(){const q=(document.getElementById("interviewSearch").value||"").toLowerCase(),d=document.getElementById("interviewDifficulty").value,sort=document.getElementById("interviewSort").value,roleFilter=document.getElementById("questionRole")?.value||"all",companyFilter=document.getElementById("questionCompany")?.value||"all";let items=state.interviews.filter(i=>(d==="all"||i.difficulty===d)&&(roleFilter==="all"||i.role.toLowerCase().includes(roleFilter.toLowerCase())||roleFilter==="Software Engineer"&&/software|sde|developer|programmer/i.test(i.role))&&(companyFilter==="all"||i.company.toLowerCase()===companyFilter.toLowerCase())&&[i.title,i.company,i.role,i.details].join(" ").toLowerCase().includes(q));items.sort((a,b)=>sort==="helpful"?b.helpful-a.helpful:b.date.localeCompare(a.date));const prompts=(window.BRMQuestionBank||[]).filter(x=>(d==="all"||x.difficulty===d)&&(roleFilter==="all"||x.role===roleFilter)&&(companyFilter==="all"||x.companies.includes(companyFilter))&&[x.question,x.topic,x.role,...x.companies].join(" ").toLowerCase().includes(q));document.getElementById("interviewCount").textContent=`${items.length} student experience${items.length===1?"":"s"} · ${prompts.length} preparation prompts matching your filters`;const experienceCards=items.map(i=>`<article class="interview-card"><div class="interview-top"><div><h3>${esc(i.title)}</h3><p>${esc(i.company)} · ${esc(i.role)} · ${esc(i.year)}</p></div><span class="tag">${esc(i.difficulty)}</span></div><p class="description">${esc(i.details.length>310?i.details.slice(0,310)+"…":i.details)}</p><div class="interview-foot"><small>${i.verified?"✓ Reviewed":"◷ Community contribution"} · ${esc(i.date)} · ${esc(i.authorName||"Student contributor")}</small><button class="helpful ${state.votes.includes(i.id)?"voted":""}" data-vote="${i.id}">♡ Helpful · ${i.helpful}</button><button class="small-action" data-detail-interview="${i.id}">Read more →</button></div></article>`);const promptCards=prompts.map(x=>`<article class="interview-card prompt-card"><div class="interview-top"><div><h3>${esc(x.question)}</h3><p>${esc(x.topic)} · ${esc(x.role)} · ${esc(x.companies.slice(0,3).join(" · "))}</p></div><span class="tag">${esc(x.difficulty)}</span></div><p class="description">Preparation prompt · Think aloud, explain your approach and discuss relevant trade-offs or complexity.</p></article>`);document.getElementById("interviewList").innerHTML=[...experienceCards,...(promptCards.length?['<div class="interview-feed-divider"><span>More interview questions to practise</span></div>']:[]),...promptCards].join("")||'<div class="empty-state">No matching experiences or questions. Try another filter or contribute an experience.</div>'}
function renderResources(){const items=state.resources.filter(r=>resourceFilter==="All"||r.category===resourceFilter);document.getElementById("resourceGrid").innerHTML=items.map(r=>`<article class="resource-card"><div class="resource-symbol">▤</div><span class="tag">${esc(r.category)}</span><h3 style="margin-top:10px">${esc(r.title)}</h3><p>${esc(r.description)}</p><div class="resource-bottom"><small class="muted">${esc(r.level)}</small><a href="${esc(r.link)}" target="_blank" rel="noopener">Open resource ↗</a></div></article>`).join("")||'<div class="empty-state">No resources in this category yet.</div>'}
function renderGuidance(){document.getElementById("guidanceGrid").innerHTML=state.guidance.map(g=>`<article class="guidance-card"><div class="mentor-avatar">${esc((g.author||"S").trim().slice(0,1).toUpperCase())}</div><h3>${esc(g.title)}</h3><p>${esc(g.text)}</p><small class="mentor-byline">${esc(g.author||"Student contributor")}</small><span class="mentor-tag">${(g.author||"").includes("Illustrative sample")?"Sample profile · not a verified testimonial":"Community guidance"}</span></article>`).join("")||'<div class="empty-state">No guidance posts yet.</div>'}
function renderAdmin(){const pending=state.submissions.filter(s=>s.status==="Pending"),approved=state.submissions.filter(s=>s.status==="Approved").slice(-5).reverse();document.getElementById("adminSummary").innerHTML=[["Pending review",pending.length],["Approved",state.submissions.filter(s=>s.status==="Approved").length],["Rejected",state.submissions.filter(s=>s.status==="Rejected").length]].map(x=>`<div class="stat-card"><div class="stat-top">${x[0]}</div><strong>${x[1]}</strong></div>`).join("");document.getElementById("pendingList").innerHTML=pending.map(s=>`<div class="submission"><div><h4>${esc(s.title)} <span class="tag">${esc(s.type)}</span></h4><p>${esc(s.company)} · ${esc(s.role||"No role supplied")} · ${esc(s.year||"Year not supplied")}<br>${esc(s.details.slice(0,260))}${s.details.length>260?"…":""}</p><small>Submitted ${esc(s.date)} · Source: ${esc(s.source||"Not supplied")}</small></div><div class="submission-actions"><button class="approve" data-review="${s.id}" data-status="Approved">Approve</button><button class="reject" data-review="${s.id}" data-status="Rejected">Reject</button></div></div>`).join("")||'<div class="empty-state">🎉 No pending submissions.</div>';document.getElementById("approvedList").innerHTML=approved.map(s=>`<div class="compact-item"><div><b>${esc(s.title)}</b><small>${esc(s.company)} · ${esc(s.type)}</small></div><span class="status">Approved</span></div>`).join("")||'<div class="empty-state">No approved submissions yet.</div>'}
function renderProfile(){const name=activeProfile?.name||"Guest student";document.getElementById("profileName").textContent=name;document.getElementById("profileRole").textContent=activeProfile?(activeProfile.course||activeProfile.email):"Sign in to your account";document.getElementById("avatarInitial").textContent=name.slice(0,1).toUpperCase();document.querySelectorAll(".admin-only").forEach(x=>x.style.display="none") }
function mergePublicPost(post){if(!post||!post.id)return;if(!state.publicPosts.some(x=>x.id===post.id))state.publicPosts.unshift(post);if(post.type==="experience"&&!state.interviews.some(x=>x.id===post.id)){state.interviews.unshift({id:post.id,title:post.title,company:post.company||"Not specified",role:post.role||"Not specified",year:post.year||"Community contribution",difficulty:post.difficulty||"Not specified",date:post.date||new Date().toISOString().slice(0,10),details:post.details||"",source:post.source||"Student contribution",helpful:0,verified:false,authorName:post.authorName||"Student contributor",authorId:post.authorId});}if(post.type==="guidance"&&!state.guidance.some(x=>x.id===post.id)){state.guidance.unshift({id:post.id,title:post.title,text:post.details||"",author:(post.authorName||"Student contributor")+(post.authorCourse?" · "+post.authorCourse:"")});}if(post.type==="resource"&&!state.resources.some(x=>x.id===post.id)){state.resources.unshift({id:post.id,title:post.title,category:post.role||"Interview",level:"Community contribution",description:post.details||"",link:post.source||"https://www.google.com/"});}}
async function syncSharedCompanies(){if(!cloudClient)return;const pill=document.querySelector(".demo-pill");try{const {data:companyRows,error:companyError}=await cloudClient.from("cc_companies").select("id,payload").order("created_at",{ascending:true});if(companyError)throw companyError;const merged=new Map(state.companies.map(c=>[c.id,c]));(companyRows||[]).forEach(r=>{if(r.payload)merged.set(r.id,r.payload)});state.companies=[...merged.values()];const {data:posts,error:postsError}=await cloudClient.from("cc_public_posts").select("id,payload").order("created_at",{ascending:false}).limit(300);if(postsError)throw postsError;const pm=new Map((posts||[]).filter(x=>x.payload).map(x=>[x.id,x.payload]));state.publicPosts=[];pm.forEach(post=>mergePublicPost(post));localStorage.setItem(KEY,JSON.stringify(state));renderAll();if(pill)pill.innerHTML="<i></i> COMMUNITY CONNECTED";}catch(err){if(pill)pill.innerHTML="<i></i> CLOUD SETUP REQUIRED";console.warn("Campus Compass shared data:",err);}}
async function publishPublicPost(post){if(!cloudClient||!activeProfile)return false;const safePost={...post,authorEmail:undefined};const {error}=await cloudClient.from("cc_public_posts").insert({id:post.id,payload:safePost,created_by:activeProfile.id});if(error)throw error;mergePublicPost(safePost);saveState();return true;}
async function publishCompanyToCloud(company){if(!cloudClient||!activeProfile)return false;const {error}=await cloudClient.from("cc_companies").insert({id:company.id,payload:company,created_by:activeProfile.id});if(error)throw error;return true;}
async function loadPrivateAccount(){if(!cloudClient||!activeProfile)return;const [{data:profile,error:profileError},{data:privateRow,error:privateError}]=await Promise.all([cloudClient.from("cc_profiles").select("full_name,course,batch").eq("id",activeProfile.id).maybeSingle(),cloudClient.from("cc_private_data").select("data").eq("user_id",activeProfile.id).maybeSingle()]);if(profileError)console.warn(profileError);if(privateError)console.warn(privateError);if(profile){activeProfile={...activeProfile,name:profile.full_name||activeProfile.name,course:profile.course||"",batch:profile.batch||""};}personalData=privateRow?.data||emptyPersonalData();renderAll();}
async function saveAccountProfile(){if(!cloudClient||!activeProfile)return;const profile={id:activeProfile.id,full_name:activeProfile.name,course:activeProfile.course||"",batch:activeProfile.batch||"",updated_at:new Date().toISOString()};const {error}=await cloudClient.from("cc_profiles").upsert(profile,{onConflict:"id"});if(error)throw error;}
function updateAuthMode(mode){authMode=mode;document.querySelectorAll("[data-auth-mode]").forEach(b=>b.classList.toggle("active",b.dataset.authMode===mode));document.querySelectorAll(".auth-signup-only").forEach(el=>el.classList.toggle("hidden",mode!=="signup"));document.getElementById("authHeading").textContent=mode==="signup"?"Create your student account":"Welcome back";document.getElementById("authIntro").textContent=mode==="signup"?"Create an account to keep your profile and preparation progress private across devices.":"Sign in to access your private profile and saved preparation progress.";document.getElementById("authSubmit").textContent=mode==="signup"?"Create account →":"Sign in →";document.getElementById("studentPassword").autocomplete=mode==="signup"?"new-password":"current-password";document.getElementById("forgotPassword").classList.toggle("hidden",mode!=="login");document.getElementById("authMessage").textContent="Your profile and roadmap are private to your account. Contributions you publish are visible to all Campus Compass visitors.";}
async function initializeCloudAuth(){const cfg=window.BRM_CLOUD||{};if(!cfg.supabaseUrl||!cfg.supabaseAnonKey||!window.supabase?.createClient){const pill=document.querySelector(".demo-pill");if(pill)pill.innerHTML="<i></i> ACCOUNT SETUP REQUIRED";return;}cloudClient=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data:{session}}=await cloudClient.auth.getSession();if(session){await applySession(session);}cloudClient.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>applySession(session),0)});await syncSharedCompanies();}
async function applySession(session){if(!session){activeProfile=null;personalData=emptyPersonalData();renderAll();return;}activeProfile={id:session.user.id,email:session.user.email,name:session.user.user_metadata?.full_name||session.user.email?.split("@")[0]||"Student",course:"",batch:""};await loadPrivateAccount();await saveAccountProfileIfMissing();renderProfile();}
async function saveAccountProfileIfMissing(){if(!activeProfile||!cloudClient)return;const {data}=await cloudClient.from("cc_profiles").select("id").eq("id",activeProfile.id).maybeSingle();if(!data)try{await saveAccountProfile()}catch(e){console.warn(e)}}
function renderPlacements(){document.getElementById("placementStats").innerHTML=placementStats.map(x=>`<article class="placement-stat"><strong>${esc(x[0])}</strong><b>${esc(x[1])}</b><small>${esc(x[2])}</small></article>`).join("");document.getElementById("placementStories").innerHTML=placementStories.map(x=>`<article class="placement-story"><div class="story-company">${esc(x[1])}</div><h4>${esc(x[0])}</h4><strong>${esc(x[2])}</strong><p>${esc(x[3])}</p><a href="https://www.lpu.in/placements.php" target="_blank" rel="noopener">LPU source ↗</a></article>`).join("")}
function roadmapTopics(path){const base=["Choose one programming language and learn its fundamentals","Practise problem solving and basic data structures","Learn Git, GitHub and command-line basics","Build and document one small project","Study core CS / domain fundamentals","Practise communication and explain your work","Create a role-focused resume and portfolio","Complete mock interviews and revise weak areas"];const specific={frontend:["HTML, semantic markup and accessibility","CSS, Flexbox, Grid and responsive layouts","JavaScript, DOM and asynchronous code","React, components, state and routing","APIs, testing and deployment"],backend:["One backend language and its ecosystem","HTTP, REST APIs and authentication","SQL, schema design and transactions","Caching, queues and system design basics","Testing, logging, deployment and security"],"full-stack":["HTML, CSS and JavaScript fundamentals","Frontend framework and component design","Backend APIs and authentication","Database modelling and SQL","Deploy a complete full-stack application"],devops:["Linux, networking and shell scripting","Git workflows and CI/CD concepts","Docker and container fundamentals","Cloud IAM, compute and networking","Kubernetes, monitoring and infrastructure as code"],"cyber-security":["Networking, TCP/IP and subnetting","Linux, Windows and operating-system fundamentals","Python scripting and basic programming","Web security and OWASP Top 10","Defensive monitoring, labs and reporting"],"ai-data-scientist":["Python, SQL and data handling","Statistics, probability and linear algebra","Data cleaning and visualization","Machine learning and model evaluation","Projects, deployment and responsible AI"],"data-analyst":["Excel / spreadsheets and data cleaning","SQL querying and joins","Statistics and business metrics","Power BI / Tableau dashboards","Portfolio case studies and storytelling"],android:["Kotlin and Android fundamentals","Layouts, UI state and navigation","Networking, storage and APIs","Architecture, testing and app security","Publish a portfolio application"],qa:["Testing fundamentals and test design","Programming and scripting basics","API testing and SQL","Automation framework fundamentals","CI pipelines, bug reports and quality metrics"],"ux-design":["User research and problem framing","Information architecture and user flows","Wireframes and visual hierarchy","Prototyping and usability testing","Case studies and design portfolio"],"computer-science":["Programming fundamentals and DSA","OOP, DBMS and SQL","Operating systems and computer networks","Software engineering and Git","Projects, problem solving and interviews"],blockchain:["Programming and web fundamentals","Cryptography and distributed systems basics","Smart contract language fundamentals","Testing, security and audit concepts","Build and document a testnet project"]};return [...(specific[path]||[]),...base]}
function renderRoadmap(){const select=document.getElementById("careerPath");if(!select)return;select.value=personalData.roadmap||"frontend";const path=select.value;const link="https://roadmap.sh/"+path;document.getElementById("openRoadmap").href=link;const topics=roadmapTopics(path);document.getElementById("roadmapChecklist").innerHTML=topics.map((t,i)=>`<label class="roadmap-check"><input type="checkbox" data-roadmap-check="${i}" ${personalData.checks.includes(path+":"+i)?"checked":""}><span>${esc(t)}</span></label>`).join("");const done=topics.filter((t,i)=>personalData.checks.includes(path+":"+i)).length;const pct=Math.round(done/topics.length*100);document.getElementById("roadmapProgress").style.width=pct+"%";document.getElementById("roadmapProgressText").textContent=pct+"% completed · "+done+" of "+topics.length+" steps"}
function renderProfilePage(){const el=document.getElementById("personalProfile");if(!el)return;el.innerHTML=activeProfile?`<div class="profile-summary"><div class="profile-avatar-large">${esc((activeProfile.name||"S").slice(0,1).toUpperCase())}</div><div><h3>${esc(activeProfile.name)}</h3><p>${esc(activeProfile.email)} · ${esc(activeProfile.course||"Course not added")} · Batch ${esc(activeProfile.batch||"—")}</p><span class="tag">Private student account</span></div></div><p class="muted">Your profile and preparation progress are private to your account. Only contributions you publish appear publicly.</p><button class="secondary-button" id="editProfile">Edit profile details</button>`:`<div class="empty-state">Sign in to view your private profile and saved roadmap. <button class="link-button" id="profileSignIn">Sign in / Create account →</button></div>`;const posts=state.publicPosts.filter(x=>x.authorId===activeProfile?.id);document.getElementById("myContributions").innerHTML=posts.map(x=>`<div class="compact-item"><div><b>${esc(x.title)}</b><small>${esc(x.type)} · ${esc(x.date||"Recently")}</small></div><span class="tag">Public post</span></div>`).join("")||'<div class="empty-state">No public contributions from this account yet.</div>'}

function renderAll(){renderDashboard();renderCompanies();renderInterviews();renderResources();renderGuidance();renderAdmin();renderProfile();renderPlacements();renderRoadmap();renderProfilePage()}
function showModal(title,body){document.getElementById("modalContent").innerHTML=`<div class="eyebrow">PLACEMENT HUB DETAILS</div><h2>${esc(title)}</h2><div class="modal-body">${body}</div>`;document.getElementById("detailModal").classList.remove("hidden")}
document.addEventListener("click",e=>{
 if(e.target.id==="profileSignIn"||e.target.id==="editProfile"){document.getElementById("openSignIn").click();return;}
 const nav=e.target.closest("[data-page]");if(nav)go(nav.dataset.page);
 const quick=e.target.closest("[data-go]");if(quick)go(quick.dataset.go);
 const comp=e.target.closest("[data-detail-company]");if(comp){const c=state.companies.find(x=>x.id===comp.dataset.detailCompany);if(c)showModal(c.name,`<div class="profile-section"><h4>Company snapshot</h4><p><b>Sector:</b> ${esc(c.category)}<br><b>Relevant stream:</b> ${esc(c.stream||"Multi-stream")}<br><b>Roles:</b> ${esc(c.roles)}<br><b>Directory status:</b> ${esc(c.status)}</p><p>${esc(c.summary)}</p></div><div class="profile-section"><h4>India locations / hiring hubs</h4><p>${esc(c.locations||"Exact company office and hiring locations are not yet verified. Check the role's official job listing.")}</p></div><div class="profile-section"><h4>Eligibility & selection</h4><p>${esc(c.eligibility||"Check the latest official job description and LPU notice.")}<br><br>${esc(c.rounds||"Current selection rounds not confirmed.")}</p></div><div class="profile-section"><h4>Skills to build</h4><p>${esc(c.skills)}</p></div><div class="profile-section"><h4>Interview preparation questions</h4><ul>${(c.questions||questionBanks.tech).map(q=>`<li>${esc(q)}</li>`).join("")}</ul><p>Practice prompts based on role expectations—not verified questions asked by this company.</p></div><div class="profile-section"><h4>Preparation roadmap</h4><p>${esc(c.roadmap||roadmapByGroup["Major Tech & Product"])}</p></div><div class="profile-section"><h4>Sources & confidence</h4><p>${esc(c.dataNote||"Verify current role, location and eligibility from the employer's official careers page and LPU placement notice.")}</p><a href="https://www.lpu.in/placements.php" target="_blank" rel="noopener">LPU official placement information ↗</a><br><a href="https://roadmap.sh" target="_blank" rel="noopener">Explore learning roadmaps at roadmap.sh ↗</a></div>`)}
 const interview=e.target.closest("[data-detail-interview]");if(interview){const i=state.interviews.find(x=>x.id===interview.dataset.detailInterview);if(i)showModal(i.title,`<b>${esc(i.company)} · ${esc(i.role)}</b>\n${esc(i.year)} · ${esc(i.difficulty)}\n\n${esc(i.details)}\n\n<b>Source:</b> ${esc(i.source||"Not supplied")}\n\n${i.verified?"Reviewed submission":"Community / demo entry — not independently verified."}`)}
 const vote=e.target.closest("[data-vote]");if(vote){const id=vote.dataset.vote;if(state.votes.includes(id)){toast("You already marked this helpful.");return}const i=state.interviews.find(x=>x.id===id);if(i){i.helpful++;state.votes.push(id);saveState();toast("Thanks for your feedback!");}}
 const review=e.target.closest("[data-review]");if(review){const s=state.submissions.find(x=>x.id===review.dataset.review);if(s){s.status=review.dataset.status;if(s.status==="Approved"){if(s.type==="experience")state.interviews.push({id:"i"+Date.now(),title:s.title,company:s.company,role:s.role||"Not specified",year:s.year||"Not specified",difficulty:["Easy","Moderate","Hard"].includes(s.level)?s.level:"Not specified",date:new Date().toISOString().slice(0,10),details:s.details,source:s.source||"Community submission",helpful:0,verified:true,authorName:s.authorName||"Student contributor"});if(s.type==="company")state.companies.push({id:"c"+Date.now(),name:s.company,category:"Technology",roles:s.role||"Not specified",status:["Open","Past drive","Research"].includes(s.level)?s.level:"Research",summary:s.details,eligibility:"See submitted details and verify against the official notice.",rounds:"Not yet confirmed. Check the current hiring notice.",skills:"See submitted details."});if(s.type==="guidance")state.guidance.push({id:"g"+Date.now(),title:s.title,text:s.details,author:(s.authorName||"Student contributor")+" · "+(s.authorCourse||"Community post")+" · Reviewed"});if(s.type==="resource")state.resources.push({id:"r"+Date.now(),title:s.title,category:["DSA","Programming Languages","Core CS","Web Development","Cybersecurity","Cloud & DevOps","Data & AI","Communication","Aptitude","Interview","Projects","Tools & Git","Design & Domain"].includes(s.role)?s.role:"Interview",level:"Community submission",description:s.details,link:s.source||"https://www.google.com/"});}saveState();toast("Submission "+s.status.toLowerCase()+".")}}
 if(e.target.id==="modalClose"||e.target.id==="detailModal")document.getElementById("detailModal").classList.add("hidden");
});
document.querySelectorAll(".nav-item").forEach(b=>b.addEventListener("click",()=>go(b.dataset.page)));
document.getElementById("companySearch").addEventListener("input",renderCompanies);["companyType","companyStatus","companyStream"].forEach(id=>document.getElementById(id).addEventListener("change",renderCompanies));
document.getElementById("refreshDirectory").addEventListener("click",()=>syncSharedCompanies());
document.getElementById("topRecruiters").addEventListener("click",e=>{const b=e.target.closest("[data-recruiter]");if(!b)return;go("companies");document.getElementById("companySearch").value=b.dataset.recruiter;renderCompanies()});
document.getElementById("interviewSearch").addEventListener("input",renderInterviews);["interviewDifficulty","interviewSort","questionRole","questionCompany"].forEach(id=>document.getElementById(id).addEventListener("change",renderInterviews));
document.getElementById("resourceTabs").addEventListener("click",e=>{const b=e.target.closest("[data-filter]");if(!b)return;resourceFilter=b.dataset.filter;document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x===b));renderResources()});
document.querySelectorAll(".form-tab").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll(".form-tab").forEach(x=>x.classList.toggle("active",x===b));document.getElementById("contributionType").value=b.dataset.form;const labels={experience:"Share an interview experience",company:"Add company information",guidance:"Share senior guidance",resource:"Suggest a preparation resource"};document.getElementById("contribTitle").placeholder=labels[b.dataset.form]}));
document.getElementById("contributionForm").addEventListener("submit",async e=>{e.preventDefault();if(!activeProfile){toast("Sign in before publishing a community contribution.");document.getElementById("openSignIn").click();return;}const type=document.getElementById("contributionType").value;const item={id:"s"+Date.now(),type,title:document.getElementById("contribTitle").value.trim(),company:document.getElementById("contribCompany").value.trim(),role:document.getElementById("contribRole").value.trim(),stream:document.getElementById("contribStream")?.value||"Multi-stream",locations:document.getElementById("contribLocations")?.value.trim()||"",skills:document.getElementById("contribSkills")?.value.trim()||"",questionsText:document.getElementById("contribQuestions")?.value.trim()||"",roadmap:document.getElementById("contribRoadmap")?.value.trim()||"",year:document.getElementById("contribYear").value.trim(),level:document.getElementById("contribLevel").value,details:document.getElementById("contribDetails").value.trim(),source:document.getElementById("contribSource").value.trim(),authorName:document.getElementById("contribAuthor").value.trim()||activeProfile.name,authorCourse:document.getElementById("contribAuthorCourse").value.trim()||activeProfile.course||"",authorId:activeProfile.id,status:"Published",date:new Date().toLocaleDateString()};if(!item.title||!item.company||!item.details)return;const publicPost={id:"post-"+Date.now(),type:item.type,title:item.title,company:item.company,role:item.role,year:item.year,difficulty:item.level,details:item.details,authorName:item.authorName,authorCourse:item.authorCourse,authorId:activeProfile.id,date:item.date,source:item.source};try{if(type==="company"){if(state.companies.some(c=>c.name.toLowerCase()===item.company.toLowerCase())){toast("This company is already listed. Share an interview experience or update instead.");return;}const company={id:"community-"+Date.now(),name:item.company,category:"Community-added",stream:item.stream,roles:item.role||"Role not yet specified",status:"Community-added",summary:item.details,eligibility:"Community-submitted. Verify against the official job description and current LPU notice.",rounds:"Not yet verified. Community members can add first-hand interview experiences.",skills:item.skills||"Not yet supplied.",locations:item.locations||"Not yet verified.",questions:item.questionsText?item.questionsText.split(/\n+/).filter(Boolean):questionBanks.multi,roadmap:item.roadmap||roadmapByGroup["Civil, Law & Specialist"],source:item.source||"Community submission",dataNote:"Community-submitted. Not independently verified."};await publishCompanyToCloud(company);state.companies.unshift(company);saveState();document.getElementById("submitSuccess").textContent="✓ Company information published. All visitors can now view it.";go("companies");}else{await publishPublicPost(publicPost);document.getElementById("submitSuccess").textContent="✓ Published to the Campus Compass community. All visitors can view this contribution.";renderAll();}document.getElementById("contributionForm").reset();document.getElementById("submitSuccess").classList.remove("hidden");toast("Published for all Campus Compass visitors.");}catch(err){console.error(err);document.getElementById("submitSuccess").textContent="Could not publish. Check your account connection and try again.";document.getElementById("submitSuccess").classList.remove("hidden");toast("Publishing failed. Please try again.");}});

document.getElementById("switchAdmin")?.remove();
document.getElementById("mobileMenu").addEventListener("click",()=>document.getElementById("sidebar").classList.toggle("open"));
document.getElementById("resetDemo")?.remove();
// Supabase student authentication and private account data.
document.getElementById("openSignIn").addEventListener("click",()=>{document.getElementById("profileMenu").classList.add("hidden");document.getElementById("signInModal").classList.remove("hidden");updateAuthMode("login");});
document.getElementById("profileButton").addEventListener("dblclick",()=>go("profile"));
document.getElementById("signInClose").addEventListener("click",()=>document.getElementById("signInModal").classList.add("hidden"));
document.getElementById("signInModal").addEventListener("click",e=>{if(e.target.id==="signInModal")e.currentTarget.classList.add("hidden")});
document.querySelectorAll("[data-auth-mode]").forEach(b=>b.addEventListener("click",()=>updateAuthMode(b.dataset.authMode)));
document.getElementById("signInForm").addEventListener("submit",async e=>{e.preventDefault();const msg=document.getElementById("authMessage"),button=document.getElementById("authSubmit");if(!cloudClient){msg.textContent="Account service is not configured yet. Add the Supabase publishable key in config.js and complete the database setup.";return;}const email=document.getElementById("studentEmail").value.trim().toLowerCase(),password=document.getElementById("studentPassword").value;button.disabled=true;button.textContent="Please wait…";try{if(authMode==="signup"){const name=document.getElementById("studentName").value.trim();const course=document.getElementById("studentCourse").value.trim();const batch=document.getElementById("studentBatch").value.trim();if(!name)throw new Error("Enter your name to create an account.");const {data,error}=await cloudClient.auth.signUp({email,password,options:{data:{full_name:name,course,batch}}});if(error)throw error;if(data.session){activeProfile={id:data.user.id,email:data.user.email,name,course,batch};await saveAccountProfile();await cloudClient.from("cc_private_data").upsert({user_id:activeProfile.id,data:emptyPersonalData()},{onConflict:"user_id"});document.getElementById("signInModal").classList.add("hidden");await applySession(data.session);toast("Your student account is ready.");}else{msg.textContent="Check your email for the verification link. After verifying, return here and sign in.";}}else{const {data,error}=await cloudClient.auth.signInWithPassword({email,password});if(error)throw error;document.getElementById("signInModal").classList.add("hidden");await applySession(data.session);toast("Signed in successfully.");}}catch(err){msg.textContent=err.message||"Authentication failed. Please try again.";}finally{button.disabled=false;button.textContent=authMode==="signup"?"Create account →":"Sign in →";}});
document.getElementById("forgotPassword").addEventListener("click",async()=>{const email=document.getElementById("studentEmail").value.trim().toLowerCase(),msg=document.getElementById("authMessage");if(!email){msg.textContent="Enter your email address first, then choose Forgot password.";return;}if(!cloudClient){msg.textContent="Account service is not configured yet.";return;}const {error}=await cloudClient.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});msg.textContent=error?error.message:"If this account exists, a password reset link has been sent to its email address.";});
document.getElementById("signOut").addEventListener("click",async()=>{if(cloudClient)await cloudClient.auth.signOut();activeProfile=null;personalData=emptyPersonalData();role="student";document.getElementById("profileMenu").classList.add("hidden");renderAll();toast("Signed out securely.");});
document.getElementById("saveRoadmap").addEventListener("click",async()=>{if(!activeProfile){document.getElementById("openSignIn").click();return;}personalData.roadmap=document.getElementById("careerPath").value;await savePersonalData();toast("Your private roadmap is saved.")});
document.getElementById("careerPath").addEventListener("change",()=>{personalData.roadmap=document.getElementById("careerPath").value;renderRoadmap()});
document.getElementById("roadmapChecklist").addEventListener("change",e=>{const box=e.target.closest("[data-roadmap-check]");if(!box)return;const key=personalData.roadmap+":"+box.dataset.roadmapCheck;if(!activeProfile){box.checked=false;document.getElementById("openSignIn").click();return;}if(box.checked&&!personalData.checks.includes(key))personalData.checks.push(key);if(!box.checked)personalData.checks=personalData.checks.filter(x=>x!==key);savePersonalData()});
document.getElementById("careerPath").addEventListener("change",()=>{document.getElementById("openRoadmap").href="https://roadmap.sh/"+document.getElementById("careerPath").value});
document.getElementById("profileButton").addEventListener("click",()=>document.getElementById("profileMenu").classList.toggle("hidden"));
document.getElementById("profileMenu").addEventListener("click",e=>{if(e.target.id==="profileSignIn")document.getElementById("openSignIn").click();if(e.target.id==="editProfile")document.getElementById("openSignIn").click()});
document.getElementById("profileSignIn")?.addEventListener("click",()=>document.getElementById("openSignIn").click());document.getElementById("editProfile")?.addEventListener("click",()=>document.getElementById("openSignIn").click());
renderAll();
initializeCloudAuth();
